50	class AscendSyncInsert : public arith::IRMutatorWithAnalyzer {
51	public:
52	  static PrimFunc Substitute(PrimFunc f, const std::string &config_path,
53	                             PassContext ctx, Target target,
54	                             std::string platform) {
55	    arith::Analyzer analyzer;
56	    AscendSyncInsert syncInserter(&analyzer, target, platform);
57	
58	    auto address_map = f->GetAttr<Map<Var, PrimExpr>>("address_map")
59	                           .value_or(Map<Var, PrimExpr>());
60	    auto size_map = f->GetAttr<Map<Var, PrimExpr>>("size_map")
61	                        .value_or(Map<Var, PrimExpr>());
62	    syncInserter.InitConfig(config_path, address_map, size_map);
63	
64	    PrimFuncNode *fptr = f.CopyOnWrite();
65	    auto fn_attr = fptr->attrs.CopyOnWrite();
66	
67	    bool ascend_auto_sync =
68	        ctx->GetConfig<Bool>(kAscendAutoSync, Bool(false)).value();
69	    if (!ascend_auto_sync) {
70	      return f;
71	    }
72	
73	    auto preprocessed = syncInserter.PreprocessUnrollForLoops(f->body);
74	
75	    Stmt processed_body = syncInserter(preprocessed.first);
76	
77	    fptr->body = syncInserter.MergeAndRebuildForLoops(processed_body,
78	                                                      preprocessed.second);
79	
80	    return f;
81	  }
82	
83	  explicit AscendSyncInsert(arith::Analyzer *analyzer, Target target,
84	                            std::string platform)
85	      : arith::IRMutatorWithAnalyzer(analyzer), target_(target),
86	        platform_(platform) {}
87	
88	private:
89	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
