91	  struct LoopInfo {
92	    Var loop_var;
93	    PrimExpr min;
94	    PrimExpr extent;
95	    ForKind kind;
96	    Map<String, ObjectRef> annotations;
97	    std::string loop_id;
98	    int depth;
99	
100	    std::string toString() const {
101	      std::ostringstream oss;
102	      oss << "LoopInfo{";
103	      oss << "loop_var: '" << loop_var->name_hint << "', ";
104	      oss << "min: " << min << ", ";
105	      oss << "extent: " << extent << ", ";
106	      oss << "kind: " << static_cast<int>(kind) << ", ";
107	      oss << "loop_id: '" << loop_id << "', ";
108	      oss << "depth: " << depth;
109	      oss << "}";
110	      return oss.str();
111	    }
112	  };
