128	  std::pair<Stmt, std::vector<LoopInfo>>
129	  PreprocessUnrollForLoops(const Stmt &stmt) {
130	    ForLoopUnroller unroller;
131	    auto result = unroller(stmt);
132	    return {result.first, result.second};
133	  }
134	
135	  Stmt VisitStmt_(const SeqStmtNode *op) override {
136	    std::vector<Stmt> new_stmts;
137	    for (const Stmt &stmt : op->seq) {
138	      new_stmts.push_back(VisitStmt(stmt));
139	    }
140	
141	    if (new_stmts.empty()) {
142	      return Evaluate(0);
143	    } else if (new_stmts.size() == 1) {
144	      return new_stmts[0];
145	    } else {
146	      return SeqStmt(new_stmts);
147	    }
148	  }
149	
150	  Stmt VisitStmt_(const EvaluateNode *op) override {
151	    auto current_accesses = AnalyzeStmtAccesses(GetRef<Stmt>(op));
152	
153	    std::vector<SyncRequirement> sync_requirements;
154	    for (const auto &current_access : current_accesses) {
155	      if (current_access.is_sliced) {
156	        sync_requirements.push_back(
157	            {"PipeBarrier_ALL", current_access.buffer_name});
158	      }
159	
160	      std::vector<std::string> related_buffers =
161	          FindRelatedBuffers(current_access.buffer_name);
162	      for (const auto &buffer_name : related_buffers) {
163	        auto it = current_access_history_.find(buffer_name);
164	        if (it != current_access_history_.end()) {
165	          const auto &latest_access = it->second;
166	          if (HasDataDependency(latest_access, current_access)) {
167	            std::string required_sync_type =
168	                GetRequiredSyncType(latest_access, current_access);
169	            if (!required_sync_type.empty()) {
170	              sync_requirements.push_back(
171	                  {required_sync_type, current_access.buffer_name});
172	            }
173	          }
174	        }
175	      }
176	    }
177	
178	    auto optimized_syncs = OptimizeSyncRequirements(sync_requirements);
179	
180	    std::vector<Stmt> stmts;
181	    for (const auto &sync_type : optimized_syncs) {
182	      InsertSynchronization(sync_type, stmts);
183	    }
184	
185	    UpdateSyncStatesAfterSync(optimized_syncs);
186	
187	    stmts.push_back(GetRef<Stmt>(op));
188	
189	    UpdateLatestAccessHistory(current_accesses);
190	
191	    if (stmts.size() == 1) {
192	      return stmts[0];
193	    } else {
194	      return SeqStmt(stmts);
195	    }
196	  }
197	
198	  Stmt VisitStmt_(const BufferStoreNode *op) override {
199	    // BufferStore is a scalar pipe operation (e.g., SetValue)
200	    // It writes to a buffer on S pipeline, and may read from buffers in the
201	    // value expression
202	
203	    // Step 1: Analyze reads in the value expression (S pipeline reads)
204	    auto value_accesses = AnalyzeExprAccesses(op->value);
205	
206	    // Step 2: Check if any read buffer needs sync (was last written by
207	    // different pipeline)
208	    // Note: Skip same-pipeline dependencies (S→S) because scalar pipeline
209	    // is in-order and doesn't need explicit sync
210	    std::vector<SyncRequirement> sync_requirements;
211	    for (auto &read_access : value_accesses) {
212	      read_access.pipeline = "PIPE_S";
213	      read_access.is_write = false;
214	      read_access.operation = "buffer_load";
215	
216	      std::vector<std::string> related_buffers =
217	          FindRelatedBuffers(read_access.buffer_name);
218	      for (const auto &buffer_name : related_buffers) {
219	        auto it = current_access_history_.find(buffer_name);
220	        if (it != current_access_history_.end()) {
221	          const auto &latest_access = it->second;
222	          // Skip same-pipeline dependencies (S→S)
223	          if (latest_access.pipeline == "PIPE_S") {
224	            continue;
225	          }
226	          if (HasDataDependency(latest_access, read_access)) {
227	            // Check if the sync has already been inserted
228	            std::string required_sync_type =
229	                GetRequiredSyncType(latest_access, read_access);
230	            if (!required_sync_type.empty()) {
231	              // Check if this sync type is already in the sync graph
232	              bool already_synced = false;
233	              if (required_sync_type.find("EventPair_") == 0) {
234	                std::string event_type = required_sync_type.substr(10);
235	                size_t pos = event_type.find('_');
236	                if (pos != std::string::npos) {
237	                  std::string src = event_type.substr(0, pos);
238	                  std::string dst = event_type.substr(pos + 1);
239	                  already_synced = latest_access.sync_graph.HasPath(src, dst);
240	                }
241	              } else if (required_sync_type.find("PipeBarrier_") == 0) {
242	                std::string pipeline = required_sync_type.substr(12);
243	                already_synced = latest_access.pipe_barriers.find(
244	                                     "PipeBarrier_" + pipeline) !=
245	                                 latest_access.pipe_barriers.end();
246	              }
247	
248	              if (!already_synced) {
249	                sync_requirements.push_back(
250	                    {required_sync_type, read_access.buffer_name});
251	              }
252	            }
253	          }
254	        }
255	      }
256	    }
257	
258	    // Step 3: Optimize and insert syncs before the BufferStore
259	    auto optimized_syncs = OptimizeSyncRequirements(sync_requirements);
260	    std::vector<Stmt> stmts;
261	    for (const auto &sync_type : optimized_syncs) {
262	      InsertSynchronization(sync_type, stmts);
263	    }
264	
265	    // Step 4: Record the write (S pipeline write)
266	    BufferAccess current_write;
267	    current_write.buffer_name = op->buffer->data->name_hint;
268	    current_write.is_write = true;
269	    current_write.pipeline = "PIPE_S";
270	    current_write.operation = "buffer_store";
271	    current_write.is_sliced = false;
272	    current_write.sync_graph = SyncGraph();
273	    current_write.pipe_barriers = {};
274	    current_write.physical_address =
275	        GetPhysicalAddress(current_write.buffer_name);
276	
277	    // Update access history for both reads and writes
278	    UpdateLatestAccessHistory(value_accesses);
279	    UpdateLatestAccessHistory({current_write});
280	
281	    // Update sync states AFTER updating access history, so that the new
282	    // accesses get the updated sync graph
283	    UpdateSyncStatesAfterSync(optimized_syncs);
284	
285	    // Step 5: Add the BufferStore statement
286	    stmts.push_back(GetRef<Stmt>(op));
287	
288	    if (stmts.size() == 1) {
289	      return stmts[0];
290	    } else {
291	      return SeqStmt(stmts);
292	    }
293	  }
294	
295	  Stmt VisitStmt_(const AttrStmtNode *op) override {
296	    if (op->attr_key == "resource_scope") {
297	      auto saved_access_history = current_access_history_;
298	
299	      current_access_history_.clear();
300	
301	      Stmt new_body = VisitStmt(op->body);
302	
303	      current_access_history_ = saved_access_history;
304	
305	      return AttrStmt(op->node, op->attr_key, op->value, new_body);
306	    } else if (op->attr_key == "unrolled_loop") {
307	      Stmt new_body = VisitStmt(op->body);
308	      return AttrStmt(op->node, op->attr_key, op->value, new_body);
309	    } else if (op->attr_key == "iteration_start" ||
310	               op->attr_key == "iteration_end") {
311	      return GetRef<Stmt>(op);
312	    }
313	
314	    Stmt new_body = VisitStmt(op->body);
315	    return AttrStmt(op->node, op->attr_key, op->value, new_body);
316	  }
317	
318	  Stmt VisitStmt_(const LetStmtNode *op) override {
319	    auto value_accesses = AnalyzeExprAccesses(op->value);
320	
321	    bool has_sliced_access = false;
322	    for (const auto &access : value_accesses) {
323	      if (access.is_sliced) {
324	        has_sliced_access = true;
325	        break;
326	      }
327	    }
328	
329	    std::vector<Stmt> stmts_before_let;
330	    if (has_sliced_access) {
331	      InsertSynchronization("PipeBarrier_ALL", stmts_before_let);
332	    }
333	
334	    Stmt new_body = VisitStmt(op->body);
335	
336	    Stmt new_let = LetStmt(op->var, op->value, new_body);
337	
338	    if (!stmts_before_let.empty()) {
339	      stmts_before_let.push_back(new_let);
340	      if (stmts_before_let.size() == 1) {
341	        return stmts_before_let[0];
342	      } else {
343	        return SeqStmt(stmts_before_let);
344	      }
345	    } else {
346	      return new_let;
347	    }
348	  }
349	
350	  Stmt VisitStmt_(const IfThenElseNode *op) override {
351	    std::vector<Stmt> stmts;
352	    InsertSynchronization("PipeBarrier_ALL", stmts);
353	
354	    current_access_history_.clear();
355	    Stmt then_case = VisitStmt(op->then_case);
356	
357	    Optional<Stmt> else_case;
358	    if (op->else_case.defined()) {
359	      current_access_history_.clear();
360	      else_case = VisitStmt(op->else_case.value());
361	    }
362	
363	    stmts.push_back(IfThenElse(op->condition, then_case, else_case));
364	
365	    InsertSynchronization("PipeBarrier_ALL", stmts);
366	    current_access_history_.clear();
367	    return SeqStmt(stmts);
368	  }
369	
370	  Stmt MergeAndRebuildForLoops(const Stmt &processed_stmt,
371	                               const std::vector<LoopInfo> &loop_infos) {
372	    LoopRebuilder rebuilder(loop_infos);
373	    return rebuilder(processed_stmt);
374	  }
