376	private:
377	  class ForLoopUnroller : public StmtMutator {
378	  public:
379	    std::pair<Stmt, std::vector<LoopInfo>> operator()(const Stmt &stmt) {
380	      loop_infos_.clear();
381	      current_depth_ = 0;
382	      Stmt result = VisitStmt(stmt);
383	      return {result, loop_infos_};
384	    }
385	
386	    Stmt VisitStmt_(const ForNode *op) override {
387	      LoopInfo info;
388	      info.loop_var = op->loop_var;
389	      info.min = op->min;
390	      info.extent = op->extent;
391	      info.kind = op->kind;
392	      info.annotations = op->annotations;
393	
394	      static int loop_counter = 0;
395	      info.loop_id = "loop_" + std::to_string(loop_counter++);
396	      info.depth = current_depth_;
397	      loop_infos_.push_back(info);
398	
399	      current_depth_++;
400	      Stmt processed_body = VisitStmt(op->body);
401	      current_depth_--;
402	
403	      std::string loop_id = info.loop_id;
404	      std::vector<Stmt> unrolled_stmts;
405	
406	      unrolled_stmts.push_back(
407	          AttrStmt(make_zero(DataType::Int(32)), "iteration_start",
408	                   StringImm(loop_id + "_iter1"), Evaluate(0)));
409	      unrolled_stmts.push_back(processed_body);
410	      unrolled_stmts.push_back(
411	          AttrStmt(make_zero(DataType::Int(32)), "iteration_end",
412	                   StringImm(loop_id + "_iter1"), Evaluate(0)));
413	
414	      unrolled_stmts.push_back(
415	          AttrStmt(make_zero(DataType::Int(32)), "iteration_start",
416	                   StringImm(loop_id + "_iter2"), Evaluate(0)));
417	      unrolled_stmts.push_back(processed_body);
418	      unrolled_stmts.push_back(
419	          AttrStmt(make_zero(DataType::Int(32)), "iteration_end",
420	                   StringImm(loop_id + "_iter2"), Evaluate(0)));
421	
422	      if (unrolled_stmts.empty()) {
423	        return Evaluate(0);
424	      }
425	
426	      Stmt unrolled_seq;
427	      if (unrolled_stmts.size() == 1) {
428	        unrolled_seq = unrolled_stmts[0];
429	      } else {
430	        unrolled_seq = SeqStmt(unrolled_stmts);
431	      }
432	
433	      return AttrStmt(make_zero(DataType::Int(32)), "unrolled_loop",
434	                      StringImm(loop_id), unrolled_seq);
435	    }
436	
437	    Stmt VisitStmt_(const SeqStmtNode *op) override {
438	      std::vector<Stmt> new_stmts;
439	      for (const Stmt &stmt : op->seq) {
440	        new_stmts.push_back(VisitStmt(stmt));
441	      }
442	      if (new_stmts.empty()) {
443	        return Evaluate(0);
444	      }
445	      return SeqStmt(new_stmts);
446	    }
447	
448	    Stmt VisitStmt_(const AttrStmtNode *op) override {
449	      Stmt new_body = VisitStmt(op->body);
450	      return AttrStmt(op->node, op->attr_key, op->value, new_body);
451	    }
452	
453	    Stmt VisitStmt_(const LetStmtNode *op) override {
454	      Stmt new_body = VisitStmt(op->body);
455	      return LetStmt(op->var, op->value, new_body);
456	    }
457	
458	  private:
459	    std::vector<LoopInfo> loop_infos_;
460	    int current_depth_ = 0;
461	  };
462	
463	  class LoopRebuilder : public StmtMutator {
464	  public:
465	    LoopRebuilder(const std::vector<LoopInfo> &loop_infos)
466	        : loop_infos_(loop_infos) {}
467	
468	    Stmt operator()(const Stmt &stmt) { return VisitStmt(stmt); }
469	
470	    Stmt VisitStmt_(const AttrStmtNode *op) override {
471	      if (op->attr_key == "unrolled_loop") {
472	        auto marker_name = op->value.as<StringImmNode>();
473	        if (marker_name) {
474	          std::string marker = marker_name->value;
475	
476	          const LoopInfo *target_info = nullptr;
477	          for (const auto &info : loop_infos_) {
478	            if (info.loop_id == marker) {
479	              target_info = &info;
480	              break;
481	            }
482	          }
483	
484	          if (target_info) {
485	            Stmt processed_body = VisitStmt(op->body);
486	
487	            Stmt merged_body =
488	                MergeIterations(processed_body, target_info->loop_id);
489	            return For(target_info->loop_var, target_info->min,
490	                       target_info->extent, target_info->kind, merged_body,
491	                       NullOpt, target_info->annotations);
492	          }
493	        }
494	      }
495	
496	      Stmt new_body = VisitStmt(op->body);
497	      return AttrStmt(op->node, op->attr_key, op->value, new_body);
498	    }
499	
500	    Stmt VisitStmt_(const SeqStmtNode *op) override {
501	      std::vector<Stmt> new_stmts;
502	      for (const Stmt &stmt : op->seq) {
503	        new_stmts.push_back(VisitStmt(stmt));
504	      }
505	      if (new_stmts.empty()) {
506	        return Evaluate(0);
507	      }
508	      return SeqStmt(new_stmts);
509	    }
510	
511	    Stmt VisitStmt_(const IfThenElseNode *op) override {
512	      Stmt then_case = VisitStmt(op->then_case);
513	
514	      Optional<Stmt> else_case;
515	      if (op->else_case.defined()) {
516	        else_case = VisitStmt(op->else_case.value());
517	      }
518	      return IfThenElse(op->condition, then_case, else_case);
519	    }
520	
521	  private:
522	    std::vector<LoopInfo> loop_infos_;
523	
524	    Stmt MergeIterations(const Stmt &unrolled_body,
525	                         const std::string &loop_id) {
526	      std::vector<Stmt> all_stmts = FlattenStmts(unrolled_body);
527	      if (all_stmts.empty()) {
528	        return Evaluate(0);
529	      }
530	
531	      std::vector<Stmt> iter1_stmts, iter2_stmts;
532	      bool in_iter1 = false;
533	      bool in_iter2 = false;
534	      std::string current_iter;
535	
536	      for (const auto &stmt : all_stmts) {
537	        if (IsEmptyEvaluate(stmt)) {
538	          continue;
539	        }
540	
541	        if (IsIterationStartMarker(stmt, loop_id + "_iter1")) {
542	          in_iter1 = true;
543	          in_iter2 = false;
544	          current_iter = "iter1";
545	          continue;
546	        } else if (IsIterationEndMarker(stmt, loop_id + "_iter1")) {
547	          in_iter1 = false;
548	          current_iter = "";
549	          continue;
550	        } else if (IsIterationStartMarker(stmt, loop_id + "_iter2")) {
551	          in_iter2 = true;
552	          in_iter1 = false;
553	          current_iter = "iter2";
554	          continue;
555	        } else if (IsIterationEndMarker(stmt, loop_id + "_iter2")) {
556	          in_iter2 = false;
557	          current_iter = "";
558	          continue;
559	        }
560	
561	        if (IsUnrolledLoopMarker(stmt)) {
562	          continue;
563	        }
564	
565	        if (in_iter1) {
566	          iter1_stmts.push_back(stmt);
567	        } else if (in_iter2) {
568	          iter2_stmts.push_back(stmt);
569	        }
570	      }
571	
572	      if (iter1_stmts.empty() && iter2_stmts.empty()) {
573	        return Evaluate(0);
574	      }
575	
576	      std::vector<Stmt> merged_stmts =
577	          MergeStatementSequences(iter1_stmts, iter2_stmts, loop_id);
578	
579	      if (merged_stmts.empty()) {
580	        return Evaluate(0);
581	      } else if (merged_stmts.size() == 1) {
582	        return merged_stmts[0];
583	      } else {
584	        return SeqStmt(merged_stmts);
585	      }
586	    }
587	
588	    bool IsIterationStartMarker(const Stmt &stmt, const std::string &marker) {
589	      if (auto attr = stmt.as<AttrStmtNode>()) {
590	        if (attr->attr_key == "iteration_start") {
591	          auto value = attr->value.as<StringImmNode>();
592	          if (value && value->value == marker) {
593	            return true;
594	          }
595	        }
596	      }
597	      return false;
598	    }
599	
600	    bool IsEmptyEvaluate(const Stmt &stmt) {
601	      if (auto eval = stmt.as<EvaluateNode>()) {
602	        if (auto int_imm = eval->value.as<IntImmNode>()) {
603	          if (int_imm->value == 0) {
604	            return true;
605	          }
606	        }
607	        if (auto float_imm = eval->value.as<FloatImmNode>()) {
608	          if (float_imm->value == 0.0) {
609	            return true;
610	          }
611	        }
612	      }
613	      return false;
614	    }
615	
616	    bool IsIterationEndMarker(const Stmt &stmt, const std::string &marker) {
617	      if (auto attr = stmt.as<AttrStmtNode>()) {
618	        if (attr->attr_key == "iteration_end") {
619	          auto value = attr->value.as<StringImmNode>();
620	          if (value && value->value == marker) {
621	            return true;
622	          }
