637	    std::vector<Stmt>
638	    MergeStatementSequences(const std::vector<Stmt> &iter1_stmts,
639	                            const std::vector<Stmt> &iter2_stmts,
640	                            const std::string &loop_id) {
641	      std::vector<Stmt> merged_stmts;
642	      std::vector<Stmt> exec_stmts;
643	      std::vector<std::vector<Stmt>> syncs_before_execs;
644	
645	      std::vector<Stmt> current_syncs;
646	      for (const auto &stmt : iter1_stmts) {
647	        if (IsSyncStatement(stmt)) {
648	          current_syncs.push_back(stmt);
649	        } else if (!IsMarkerStatement(stmt)) {
650	          exec_stmts.push_back(stmt);
651	          syncs_before_execs.push_back(current_syncs);
652	          current_syncs.clear();
653	        }
654	      }
655	
656	      if (!current_syncs.empty()) {
657	        syncs_before_execs.push_back(current_syncs);
658	        current_syncs.clear();
659	      }
660	
661	      std::vector<std::vector<Stmt>> iter2_syncs_before_execs(
662	          exec_stmts.size());
663	      size_t exec_index = 0;
664	      for (const auto &stmt : iter2_stmts) {
665	        if (IsSyncStatement(stmt)) {
666	          if (exec_index < iter2_syncs_before_execs.size()) {
667	            iter2_syncs_before_execs[exec_index].push_back(stmt);
668	          } else {
669	            current_syncs.push_back(stmt);
670	          }
671	        } else if (!IsMarkerStatement(stmt)) {
672	          exec_index++;
673	        }
674	      }
675	
676	      if (!current_syncs.empty()) {
677	        iter2_syncs_before_execs.push_back(current_syncs);
678	      }
679	
680	      std::vector<std::vector<Stmt>> merged_syncs_before_execs;
681	      for (size_t i = 0; i < syncs_before_execs.size(); i++) {
682	        std::vector<Stmt> merged_syncs = syncs_before_execs[i];
683	        if (i < iter2_syncs_before_execs.size()) {
684	          for (const auto &sync : iter2_syncs_before_execs[i]) {
685	            if (std::find(merged_syncs.begin(), merged_syncs.end(), sync) ==
686	                merged_syncs.end()) {
687	              merged_syncs.push_back(sync);
688	            }
689	          }
690	        }
691	        merged_syncs_before_execs.push_back(merged_syncs);
692	      }
693	
694	      for (size_t i = 0; i < exec_stmts.size(); i++) {
695	        std::vector<Stmt> syncs;
696	        for (const auto &sync : merged_syncs_before_execs[i]) {
697	          if (!ContainsSync(syncs, sync)) {
698	            syncs.push_back(sync);
699	            merged_stmts.push_back(sync);
700	          }
701	        }
702	        merged_stmts.push_back(exec_stmts[i]);
703	      }
704	
705	      if (merged_syncs_before_execs.size() > exec_stmts.size()) {
706	        for (const auto &sync : merged_syncs_before_execs[exec_stmts.size()]) {
707	          merged_stmts.push_back(sync);
708	        }
709	      }
710	
711	      return merged_stmts;
712	    }
