723	    bool IsSyncStatement(const Stmt &stmt) {
724	      if (auto eval = stmt.as<EvaluateNode>()) {
725	        if (auto call = eval->value.as<CallNode>()) {
726	          if (call->op.same_as(builtin::call_extern())) {
727	            auto func_name_imm = call->args[0].as<StringImmNode>();
728	            if (func_name_imm) {
729	              std::string func_name = func_name_imm->value;
730	              return ((func_name.find("AutoBarrier") != std::string::npos ||
731	                       func_name.find("AutoSetFlag") != std::string::npos ||
732	                       func_name.find("AutoWaitFlag") != std::string::npos));
733	            }
734	          } else if (call->op.same_as(tl::ascend_auto_barrier()) ||
735	                     call->op.same_as(tl::ascend_auto_set_flag()) ||
736	                     call->op.same_as(tl::ascend_auto_wait_flag())) {
737	            return true;
738	          }
739	        }
740	      }
741	      return false;
742	    }
