744	    bool ContainsSync(const std::vector<Stmt> &stmts, const Stmt &sync_stmt) {
745	      for (const auto &stmt : stmts) {
746	        if (IsSyncStatement(stmt) && IsSameSyncOperation(stmt, sync_stmt)) {
747	          return true;
