753	    bool IsSameSyncOperation(const Stmt &stmt1, const Stmt &stmt2) {
754	      if (!IsSyncStatement(stmt1) || !IsSyncStatement(stmt2)) {
755	        return false;
756	      }
757	
758	      auto eval1 = stmt1.as<EvaluateNode>();
759	      auto eval2 = stmt2.as<EvaluateNode>();
760	      if (!eval1 || !eval2) {
761	        return false;
762	      }
763	
764	      auto call1 = eval1->value.as<CallNode>();
765	      auto call2 = eval2->value.as<CallNode>();
766	      if (!call1 || !call2) {
767	        return false;
768	      }
769	
770	      if (call1->op.same_as(builtin::call_extern()) &&
771	          call2->op.same_as(builtin::call_extern())) {
772	        auto func_name1 = call1->args[0].as<StringImmNode>();
773	        auto func_name2 = call2->args[0].as<StringImmNode>();
774	        if (!func_name1 || !func_name2) {
775	          return false;
776	        }
777	
778	        std::string name1 = func_name1->value;
779	        std::string name2 = func_name2->value;
780	
781	        if (name1 != name2) {
782	          return false;
783	        }
784	
785	        if (name1.find("AutoBarrier") != std::string::npos) {
786	          if (call1->args.size() >= 2 && call2->args.size() >= 2) {
787	            auto pipeline1 = call1->args[1].as<StringImmNode>();
788	            auto pipeline2 = call2->args[1].as<StringImmNode>();
789	            if (pipeline1 && pipeline2) {
790	              return pipeline1->value == pipeline2->value;
791	            }
792	          }
793	          return false;
794	        }
795	
796	        if (name1.find("AutoSetFlag") != std::string::npos ||
797	            name1.find("AutoWaitFlag") != std::string::npos) {
798	          if (call1->args.size() >= 3 && call2->args.size() >= 3) {
799	            auto event_type1 = call1->args[1].as<StringImmNode>();
800	            auto event_type2 = call2->args[1].as<StringImmNode>();
801	            if (event_type1 && event_type2) {
802	              return event_type1->value == event_type2->value;
803	            }
804	          }
805	          return false;
806	        }
807	
808	        return StructuralEqual()(stmt1, stmt2);
809	      } else if (call1->op.same_as(call2->op)) {
810	        // call_intrin 判断
811	        // std::string op_name;
812	        // if (auto* op_ptr = call1->op.as<OpNode>()) {
813	        //     op_name = op_ptr->name;
814	        //     auto config_it = operation_config_.find(op_name);
815	        //     if (config_it == operation_config_.end()){
816	        //         return false;
817	        //     }
818	        // }
819	
820	        if (call1->op.same_as(tl::ascend_auto_barrier())) {
821	          if (call1->args.size() >= 1 && call2->args.size() >= 1) {
822	            auto pipeline1 = call1->args[0].as<StringImmNode>();
823	            auto pipeline2 = call2->args[0].as<StringImmNode>();
824	            if (pipeline1 && pipeline2) {
825	              return pipeline1->value == pipeline2->value;
826	            }
827	          }
828	          return false;
829	        }
830	
831	        if (call1->op.same_as(tl::ascend_auto_set_flag()) ||
832	            call1->op.same_as(tl::ascend_auto_wait_flag())) {
833	          if (call1->args.size() >= 2 && call2->args.size() >= 2) {
834	            auto event_type1 = call1->args[0].as<StringImmNode>();
835	            auto event_type2 = call2->args[0].as<StringImmNode>();
836	            if (event_type1 && event_type2) {
837	              return event_type1->value == event_type2->value;
838	            }
839	          }
840	          return false;
841	        }
842	        return StructuralEqual()(stmt1, stmt2);
843	      }
844	
845	      return false;
846	    }
