913	  struct SyncGraph {
914	    std::unordered_map<std::string, std::unordered_set<std::string>> graph;
915	
916	    std::string toString() const {
917	      std::ostringstream oss;
918	      oss << "SyncGraph{graph: {";
919	      bool first_pair = true;
920	      for (const auto &pair : graph) {
921	        if (!first_pair)
922	          oss << ", ";
923	        oss << "'" << pair.first << "': [";
924	        bool first_dst = true;
925	        for (const auto &dst : pair.second) {
926	          if (!first_dst)
927	            oss << ", ";
928	          oss << "'" << dst << "'";
929	          first_dst = false;
930	        }
931	        oss << "]";
932	        first_pair = false;
933	      }
934	      oss << "}}";
935	      return oss.str();
936	    }
937	
938	    void AddSync(const std::string &sync_type) {
939	      if (sync_type.find("EventPair_") == 0) {
940	        std::string event = sync_type.substr(10);
941	        size_t pos = event.find('_');
942	        if (pos != std::string::npos) {
943	          std::string src = event.substr(0, pos);
944	          std::string dst = event.substr(pos + 1);
945	          graph[src].insert(dst);
946	        }
947	      }
948	    }
949	
950	    bool HasPath(const std::string &src, const std::string &dst) const {
951	      if (src == dst)
952	        return true;
953	
954	      std::unordered_set<std::string> visited;
955	      std::vector<std::string> queue = {src};
956	      visited.insert(src);
957	
958	      while (!queue.empty()) {
959	        std::string current = queue.back();
960	        queue.pop_back();
961	
962	        auto it = graph.find(current);
963	        if (it != graph.end()) {
964	          for (const auto &neighbor : it->second) {
965	            if (neighbor == dst)
966	              return true;
967	            if (visited.count(neighbor) == 0) {
968	              visited.insert(neighbor);
969	              queue.push_back(neighbor);
970	            }
971	          }
972	        }
973	      }
974	
975	      return false;
976	    }
977	
978	    void Merge(const SyncGraph &other) {
979	      for (const auto &pair : other.graph) {
980	        const std::string &src = pair.first;
981	        for (const std::string &dst : pair.second) {
982	          graph[src].insert(dst);
983	        }
984	      }
985	    }
986	
987	    SyncGraph ComputeTransitiveClosure() const {
988	      SyncGraph closure;
989	      closure.graph = graph;
990	
991	      std::unordered_set<std::string> nodes;
992	      for (const auto &pair : graph) {
993	        nodes.insert(pair.first);
994	        for (const auto &dst : pair.second) {
995	          nodes.insert(dst);
996	        }
997	      }
998	
999	      std::vector<std::string> node_list(nodes.begin(), nodes.end());
1000	
1001	      for (const auto &k : node_list) {
1002	        for (const auto &i : node_list) {
1003	          for (const auto &j : node_list) {
1004	            if (closure.HasPath(i, k) && closure.HasPath(k, j)) {
1005	              closure.graph[i].insert(j);
1006	            }
1007	          }
1008	        }
1009	      }
1010	
1011	      return closure;
1012	    }
1013	  };
