1199	    if (auto eval = stmt.as<EvaluateNode>()) {
1200	      if (auto call = eval->value.as<CallNode>()) {
1201	        if (call->op.same_as(builtin::call_extern())) {
1202	          std::string func_name = Downcast<StringImm>(call->args[0])->value;
1203	
1204	          std::string normalized_name = NormalizeFunctionName(func_name);
1205	          auto config_it = operation_config_.find(normalized_name);
1206	          if (config_it != operation_config_.end()) {
1207	            const auto &config = config_it->second;
1208	
1209	            std::unordered_map<std::string, BufferAccess> buffer_access_map;
1210	
1211	            for (const auto &buffer_config : config.buffer_accesses) {
1212	              size_t arg_index = buffer_config.first;
1213	              const std::string &access_type = buffer_config.second;
1214	
1215	              if (arg_index + 1 < call->args.size()) {
1216	                auto buffer_info =
1217	                    ExtractBufferInfoFromAccessPtr(call->args[arg_index + 1]);
1218	                if (!buffer_info.buffer_name.empty()) {
1219	                  bool is_write = (access_type == "write");
1220	
1221	                  if (buffer_access_map.find(buffer_info.buffer_name) !=
1222	                      buffer_access_map.end()) {
1223	                    BufferAccess &existing_access =
1224	                        buffer_access_map[buffer_info.buffer_name];
1225	                    if (is_write || (!existing_access.is_write && is_write)) {
1226	                      existing_access.is_write = true;
1227	                    }
1228	                    existing_access.is_sliced =
1229	                        existing_access.is_sliced || buffer_info.is_sliced;
1230	                  } else {
1231	                    BufferAccess access;
1232	                    access.sync_graph = SyncGraph();
1233	                    access.pipe_barriers = {};
1234	                    access.physical_address =
1235	                        GetPhysicalAddress(buffer_info.buffer_name);
1236	
1237	                    access.buffer_name = buffer_info.buffer_name;
1238	                    access.is_write = is_write;
1239	                    access.pipeline = config.default_pipeline;
1240	                    access.operation = normalized_name;
1241	                    access.is_sliced = buffer_info.is_sliced;
1242	
1243	                    buffer_access_map[buffer_info.buffer_name] = access;
1244	                  }
1245	                }
1246	              }
1247	            }
1248	
1249	            for (const auto &pair : buffer_access_map) {
1250	              accesses.push_back(pair.second);
1251	            }
1252	          }
1253	        } else { //
1254	          std::string op_name;
1255	          if (auto *op_ptr = call->op.as<OpNode>()) {
1256	            op_name = op_ptr->name;
1257	
1258	            std::string normalized_name = op_name;
1259	
1260	            auto config_it = operation_config_.find(normalized_name);
1261	            if (config_it != operation_config_.end()) {
1262	              const auto &config = config_it->second;
1263	
1264	              std::unordered_map<std::string, BufferAccess> buffer_access_map;
1265	
1266	              for (const auto &buffer_config : config.buffer_accesses) {
1267	                size_t arg_index = buffer_config.first;
1268	                const std::string &access_type = buffer_config.second;
1269	
1270	                if (arg_index < call->args.size()) {
1271	                  auto buffer_info =
1272	                      ExtractBufferInfoFromAccessPtr(call->args[arg_index]);
1273	                  if (!buffer_info.buffer_name.empty()) {
1274	                    bool is_write = (access_type == "write");
1275	
1276	                    if (buffer_access_map.find(buffer_info.buffer_name) !=
1277	                        buffer_access_map.end()) {
1278	                      BufferAccess &existing_access =
1279	                          buffer_access_map[buffer_info.buffer_name];
1280	                      if (is_write || (!existing_access.is_write && is_write)) {
1281	                        existing_access.is_write = true;
1282	                      }
1283	                      existing_access.is_sliced =
1284	                          existing_access.is_sliced || buffer_info.is_sliced;
1285	                    } else {
1286	                      BufferAccess access;
1287	                      access.sync_graph = SyncGraph();
1288	                      access.pipe_barriers = {};
1289	                      access.physical_address =
1290	                          GetPhysicalAddress(buffer_info.buffer_name);
1291	
1292	                      access.buffer_name = buffer_info.buffer_name;
1293	                      access.is_write = is_write;
1294	                      access.pipeline = config.default_pipeline;
1295	                      access.operation = normalized_name;
1296	                      access.is_sliced = buffer_info.is_sliced;
1297	
1298	                      buffer_access_map[buffer_info.buffer_name] = access;
1299	                    }
1300	                  }
1301	                }
1302	              }
1303	
1304	              for (const auto &pair : buffer_access_map) {
1305	                accesses.push_back(pair.second);
1306	              }
1307	            }
1308	          }
1309	        }
1310	      }
1311	    }
1312	
1313	    return accesses;
1314	  }
1315	
1316	  std::string NormalizeFunctionName(const std::string &func_name) {
1317	    std::string result = func_name;
1318	    size_t template_pos = result.find('<');
1319	    if (template_pos != std::string::npos) {
1320	      result = result.substr(0, template_pos);
1321	    }
1322	
1323	    size_t ns_pos = result.find("tl::ascend::");
1324	    if (ns_pos != std::string::npos) {
1325	      result = result.substr(ns_pos + 12);
1326	    }
1327	
1328	    return result;
1329	  }
1330	
1331	  BufferInfo ExtractBufferInfoFromAccessPtr(const PrimExpr &expr) {
1332	    BufferInfo info = {"", false, false};
1333	
1334	    if (auto call = expr.as<CallNode>()) {
1335	      if (call->op.same_as(builtin::tvm_access_ptr())) {
1336	        if (call->args.size() >= 5) {
1337	          if (auto var = call->args[1].as<VarNode>()) {
1338	            info.buffer_name = var->name_hint;
1339	          }
1340	
1341	          ExprAccessAnalyzer analyzer;
1342	          analyzer(call->args[2]);
1343	          for (const auto &buffer_name : analyzer.GetAccessedBuffers()) {
1344	            if (analyzer.IsBufferSliced(buffer_name)) {
1345	              info.is_sliced = true;
1346	            }
1347	          }
1348	
1349	          if (auto access_mask = call->args[4].as<IntImmNode>()) {
1350	            int mask = access_mask->value;
1351	            info.is_read = (mask & 1) != 0;
1352	            info.is_write = (mask & 2) != 0;
1353	          }
1354	        }
1355	      } else {
1356	        if (call->args.size() >= 2) {
1357	          if (auto var = call->args[1].as<VarNode>()) {
1358	            info.buffer_name = var->name_hint;
1359	            info.is_read = true;
1360	            info.is_write = true;
1361	          }
1362	        }
1363	      }
1364	    }
1365	
1366	    return info;
1367	  }
1368	
1369	  bool HasDataDependency(const BufferAccess &prev, const BufferAccess &curr) {
1370	    bool shares_memory = false;
1371	
1372	    if (prev.buffer_name == curr.buffer_name) {
1373	      shares_memory = true;
1374	    } else if (prev.physical_address != -1 && curr.physical_address != -1) {
1375	      int64_t prev_size = GetBufferSize(prev.buffer_name);
1376	      int64_t curr_size = GetBufferSize(curr.buffer_name);
1377	      if (prev_size > 0 && curr_size > 0) {
1378	        int64_t prev_end = prev.physical_address + prev_size;
1379	        int64_t curr_end = curr.physical_address + curr_size;
1380	        shares_memory = (prev.physical_address < curr_end &&
1381	                         curr.physical_address < prev_end);
1382	      } else {
1383	        shares_memory = (prev.physical_address == curr.physical_address);
1384	      }
1385	    }
1386	
1387	    if (shares_memory) {
1388	      if ((prev.is_write && curr.is_write) ||  // WAW
1389	          (prev.is_write && !curr.is_write) || // RAW
1390	          (!prev.is_write && curr.is_write)) { // WAR
1391	        return true;
1392	      }
1393	    }
1394	    return false;
1395	  }
1396	
1397	  void
1398	  UpdateLatestAccessHistory(const std::vector<BufferAccess> &current_accesses) {
1399	    for (const auto &access : current_accesses) {
1400	      current_access_history_[access.buffer_name] = access;
1401	    }
1402	  }
1403	
1404	  std::string GetRequiredSyncType(const BufferAccess &prev_access,
1405	                                  const BufferAccess &curr_access) {
1406	    if (prev_access.pipeline == curr_access.pipeline &&
1407	        prev_access.pipe_barriers.find("PipeBarrier_" + prev_access.pipeline) ==
1408	            prev_access.pipe_barriers.end()) {
1409	      return "PipeBarrier_" + prev_access.pipeline;
1410	    } else {
1411	      std::string event_type =
1412	          GetEventType(prev_access.pipeline, curr_access.pipeline);
1413	      if (!event_type.empty()) {
1414	        return "EventPair_" + event_type;
1415	      }
1416	    }
1417	    return "";
1418	  }
1419	
1420	  std::string GetEventType(const std::string &src_pipeline,
1421	                           const std::string &dst_pipeline) {
1422	    std::string key = src_pipeline + "_" + dst_pipeline;
1423	    auto it = event_mapping_.find(key);
1424	    return it != event_mapping_.end() ? it->second : "";
1425	  }
1426	
1427	  int64_t GetPhysicalAddress(const std::string &buffer_name) {
1428	    for (const auto &pair : address_map_) {
1429	      if (pair.first->name_hint == buffer_name) {
1430	        if (auto int_imm = pair.second.as<IntImmNode>()) {
1431	          return int_imm->value;
1432	        }
1433	      }
1434	    }
1435	    return -1;
1436	  }
1437	
1438	  int64_t GetBufferSize(const std::string &buffer_name) {
1439	    for (const auto &pair : size_map_) {
1440	      if (pair.first->name_hint == buffer_name) {
1441	        if (auto int_imm = pair.second.as<IntImmNode>()) {
1442	          return int_imm->value;
1443	        }
1444	      }
1445	    }
1446	    return -1;
1447	  }
1448	
1449	  std::string GetBufferScope(const std::string &buffer_name) {
1450	    for (const auto &pair : address_map_) {
1451	      if (pair.first->name_hint == buffer_name) {
1452	        return GetPtrStorageScope(pair.first);
1453	      }
1454	    }
1455	    return "";
1456	  }
1457	
1458	  std::vector<std::string> FindRelatedBuffers(const std::string &buffer_name) {
1459	    std::vector<std::string> related;
1460	    int64_t target_addr = GetPhysicalAddress(buffer_name);
1461	
1462	    if (target_addr == -1) {
1463	      related.push_back(buffer_name);
1464	      return related;
1465	    }
1466	
1467	    std::string target_scope = GetBufferScope(buffer_name);
1468	
1469	    int64_t target_size = GetBufferSize(buffer_name);
1470	    if (target_size <= 0) {
1471	      // No size info, fall back to exact address match
1472	      for (const auto &pair : address_map_) {
1473	        if (auto int_imm = pair.second.as<IntImmNode>()) {
1474	          if (int_imm->value == target_addr &&
1475	              GetPtrStorageScope(pair.first) == target_scope) {
1476	            related.push_back(pair.first->name_hint);
1477	          }
1478	        }
1479	      }
1480	      return related;
1481	    }
1482	
1483	    int64_t target_end = target_addr + target_size;
1484	
1485	    for (const auto &pair : address_map_) {
1486	      if (auto int_imm = pair.second.as<IntImmNode>()) {
1487	        if (GetPtrStorageScope(pair.first) != target_scope) {
1488	          continue;
1489	        }
1490	        int64_t other_addr = int_imm->value;
1491	        int64_t other_size = GetBufferSize(pair.first->name_hint);
1492	        if (other_size <= 0) {
1493	          // No size info for other buffer, check exact match only
1494	          if (other_addr == target_addr) {
1495	            related.push_back(pair.first->name_hint);
1496	          }
1497	          continue;
1498	        }
1499	        int64_t other_end = other_addr + other_size;
1500	        // Check interval overlap: [target_addr, target_end) ∩ [other_addr,
1501	        // other_end)
1502	        if (target_addr < other_end && other_addr < target_end) {
1503	          related.push_back(pair.first->name_hint);
1504	        }
1505	      }
1506	    }
1507	    return related;
1508	  }
1509	
1510	  std::vector<std::string>
1511	  OptimizeSyncRequirements(const std::vector<SyncRequirement> &requirements) {
1512	    if (requirements.empty()) {
1513	      return {};
1514	    }
1515	
1516	    std::vector<std::string> all_required_syncs;
1517	    for (const auto &req : requirements) {
1518	      all_required_syncs.push_back(req.sync_type);
1519	    }
1520	
1521	    std::sort(all_required_syncs.begin(), all_required_syncs.end());
1522	    all_required_syncs.erase(
1523	        std::unique(all_required_syncs.begin(), all_required_syncs.end()),
1524	        all_required_syncs.end());
1525	
1526	    std::vector<std::string> final_syncs;
1527	
1528	    for (const auto &sync_type : all_required_syncs) {
1529	      bool needed = false;
1530	
1531	      for (const auto &req : requirements) {
1532	        if (req.sync_type == sync_type) {
1533	          SyncGraph extended_graph = GetBufferSyncGraph(req.buffer_name);
1534	
1535	          for (const auto &other_sync : all_required_syncs) {
1536	            if (other_sync != sync_type) {
1537	              extended_graph.AddSync(other_sync);
1538	            }
1539	          }
1540	
1541	          if (!IsSyncSatisfiedByGraph(sync_type, extended_graph)) {
1542	            needed = true;
1543	            break;
1544	          }
1545	        }
1546	      }
1547	
1548	      if (needed) {
1549	        final_syncs.push_back(sync_type);
1550	      }
1551	    }
1552	
1553	    return final_syncs;
1554	  }
1555	
1556	  SyncGraph GetBufferSyncGraph(const std::string &buffer_name) {
1557	    auto it = current_access_history_.find(buffer_name);
1558	    if (it != current_access_history_.end()) {
1559	      return it->second.sync_graph;
1560	    }
1561	    return SyncGraph();
1562	  }
1563	
1564	  bool IsSyncSatisfiedByGraph(const std::string &sync_type,
1565	                              const SyncGraph &graph) {
1566	    if (sync_type.find("EventPair_") == 0) {
1567	      std::string target_event = sync_type.substr(10);
1568	      size_t pos = target_event.find('_');
1569	      if (pos != std::string::npos) {
1570	        std::string target_src = target_event.substr(0, pos);
1571	        std::string target_dst = target_event.substr(pos + 1);
1572	        return graph.HasPath(target_src, target_dst);
1573	      }
1574	    }
1575	    return false;
1576	  }
1577	
1578	  void
1579	  UpdateSyncStatesAfterSync(const std::vector<std::string> &inserted_syncs) {
1580	    SyncGraph inserted_graph;
1581	    for (const auto &sync_type : inserted_syncs) {
1582	      inserted_graph.AddSync(sync_type);
1583	    }
1584	
1585	    SyncGraph transitive_closure = inserted_graph.ComputeTransitiveClosure();
1586	
1587	    for (auto &pair : current_access_history_) {
1588	      BufferAccess &access = pair.second;
1589	
1590	      for (const auto &sync_type : inserted_syncs) {
1591	        if (sync_type.find("EventPair_") == 0) {
1592	          access.sync_graph.AddSync(sync_type);
1593	        } else if (sync_type.find("PipeBarrier_") == 0) {
1594	          std::string pipeline = sync_type.substr(12);
1595	          if (access.pipeline == pipeline) {
1596	            access.pipe_barriers.insert(sync_type);
1597	          }
1598	        }
1599	      }
1600	
1601	      access.sync_graph.Merge(transitive_closure);
1602	    }
1603	  }
1604	
1605	  void InsertSynchronization(const std::string &sync_type,
1606	                             std::vector<Stmt> &stmts) {
1607	    if (sync_type == "PipeBarrier_ALL") {
1608	      stmts.push_back(CreatePipeBarrier("PIPE_ALL"));
1609	    } else if (sync_type.find("PipeBarrier_") == 0) {
1610	      std::string pipeline = sync_type.substr(12);
1611	      // A5 AIC dont need PIPE_V
1612	      if (pipeline == "PIPE_V" && this->platform_ == "A5") {
1613	        return;
1614	      }
1615	      stmts.push_back(CreatePipeBarrier(pipeline));
1616	    } else if (sync_type.find("EventPair_") == 0) {
1617	      std::string event_type = sync_type.substr(10);
1618	      int event_id = AllocateEventId();
1619	      stmts.push_back(CreateSetFlag(event_type, event_id));
1620	      stmts.push_back(CreateWaitFlag(event_type, event_id));
1621	    }
1622	  }
1623	
1624	  int AllocateEventId() {
1625	    event_id_counter_ = (event_id_counter_ + 1) % 8;
1626	    return event_id_counter_;
1627	  }
1628	
1629	  Stmt CreatePipeBarrier(const std::string &pipeline) {
1630	    Array<PrimExpr> args = {StringImm(pipeline)};
1631	    return Evaluate(
1632	        Call(DataType::Handle(), Op::Get("tl.ascend_auto_barrier"), args));
1633	  }
1634	
1635	  Stmt CreateSetFlag(const std::string &event_type, int event_id) {
1636	    Array<PrimExpr> args = {StringImm(event_type),
1637	                            IntImm(DataType::Int(32), event_id)};
1638	    return Evaluate(
1639	        Call(DataType::Handle(), Op::Get("tl.ascend_auto_set_flag"), args));
1640	  }
1641	
1642	  Stmt CreateWaitFlag(const std::string &event_type, int event_id) {
1643	    Array<PrimExpr> args = {StringImm(event_type),
1644	                            IntImm(DataType::Int(32), event_id)};
1645	    return Evaluate(
1646	        Call(DataType::Handle(), Op::Get("tl.ascend_auto_wait_flag"), args));
1647	  }
1648	
1649	private:
1650	  int event_id_counter_ = 0;
1651	  std::unordered_map<std::string, std::string> event_mapping_;
1652	  std::unordered_map<std::string, OperationConfig> operation_config_;
1653	  std::unordered_map<std::string, BufferAccess> current_access_history_;
1654	  Map<Var, PrimExpr> address_map_;
1655	  Map<Var, PrimExpr> size_map_;
1656	  std::string platform_;
1657	  Target target_;
1658	};
1659	
1660	tvm::transform::Pass AscendSyncInsert(Target target, std::string platform) {
1661	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
1662	    auto new_func = AscendSyncInsert::Substitute(std::move(f), "config_path",
1663	                                                 ctx, target, platform);
1664	    return new_func;
1665	  };
1666	  return CreatePrimFuncPass(pass_func, 0, "tl.AscendSyncInsert", {});
1667	}
1668	
1669	TVM_REGISTER_GLOBAL("tl.transform.AscendSyncInsert")
1670	    .set_body_typed(AscendSyncInsert);
1671	
1672	} // namespace tl
1673	} // namespace tvm
