76	  struct BufferAccess {
77	    std::string buffer_name;
78	    bool is_write;
79	    std::string pipeline;
80	    std::string operation;
81	    std::set<std::string> pipe_barriers;
82	    std::set<std::string> event_pairs;
83	    int64_t physical_address;
84	    bool is_back_edge = false;
