107	  // ==================== VisitStmt overrides ====================
108	
109	  Stmt VisitStmt_(const SeqStmtNode *op) override {
110	    std::vector<Stmt> new_stmts;
111	    for (const Stmt &stmt : op->seq) {
112	      new_stmts.push_back(VisitStmt(stmt));
113	    }
114	    if (new_stmts.empty()) {
115	      return Evaluate(0);
116	    }
117	    if (new_stmts.size() == 1) {
118	      return new_stmts[0];
119	    }
120	    return SeqStmt(new_stmts);
121	  }
122	
123	  Stmt VisitStmt_(const EvaluateNode *op) override {
124	    if (auto call = op->value.as<CallNode>()) {
125	      if (call->op.same_as(tl::ascend_auto_barrier())) {
126	        if (call->args.size() >= 1) {
127	          if (auto str = call->args[0].as<StringImmNode>()) {
128	            std::string pipeline = str->value;
129	            std::string barrier = "PipeBarrier_" + pipeline;
130	            for (auto &pair : current_access_history_) {
131	              if (pair.second.pipeline == pipeline) {
132	                pair.second.pipe_barriers.insert(barrier);
133	              }
134	            }
135	            for (auto &pair : current_write_history_) {
136	              if (pair.second.pipeline == pipeline) {
137	                pair.second.pipe_barriers.insert(barrier);
138	              }
139	            }
140	          }
141	        }
142	        return GetRef<Stmt>(op);
143	      }
144	
145	      if (call->op.same_as(tl::ascend_auto_set_flag()) ||
146	          call->op.same_as(tl::ascend_auto_wait_flag())) {
147	        if (call->args.size() >= 1) {
148	          if (auto str = call->args[0].as<StringImmNode>()) {
149	            std::string event_type = str->value;
150	            std::string event_sync = "EventPair_" + event_type;
151	            size_t pos = event_type.find('_');
152	            if (pos != std::string::npos) {
153	              std::string src_pipeline = "PIPE_" + event_type.substr(0, pos);
154	              auto update_hist =
155	                  [&](std::unordered_map<std::string, BufferAccess> &hist) {
156	                    for (auto &pair : hist) {
157	                      if (pair.second.pipeline == src_pipeline) {
158	                        pair.second.event_pairs.insert(event_sync);
159	                      }
160	                    }
161	                  };
162	              update_hist(current_access_history_);
163	              update_hist(current_write_history_);
164	            }
165	          }
166	        }
167	        return GetRef<Stmt>(op);
168	      }
169	    }
170	
171	    auto current_accesses = AnalyzeStmtAccesses(GetRef<Stmt>(op));
172	
173	    auto scalar_reads = ScanBufferLoads(op->value);
174	    for (const auto &read : scalar_reads) {
175	      bool found = false;
176	      for (const auto &acc : current_accesses) {
177	        if (acc.buffer_name == read.buffer_name) {
178	          found = true;
179	          break;
180	        }
181	      }
182	      if (!found) {
183	        current_accesses.push_back(read);
184	      }
185	    }
186	
187	    return ProcessStatement(GetRef<Stmt>(op), current_accesses);
188	  }
189	
190	  Stmt VisitStmt_(const BufferStoreNode *op) override {
191	    std::string scope = GetPtrStorageScope(op->buffer->data);
192	
193	    std::vector<BufferAccess> current_accesses;
194	
195	    if (scope != "local.var" && scope != "n") {
196	      BufferAccess write_access;
197	      write_access.buffer_name = op->buffer->data->name_hint;
198	      write_access.is_write = true;
199	      write_access.pipeline = "PIPE_S";
200	      write_access.operation = "BufferStore";
201	      write_access.physical_address =
202	          GetPhysicalAddress(write_access.buffer_name);
203	      current_accesses.push_back(write_access);
204	    }
205	
206	    auto scalar_reads = ScanBufferLoads(op->value);
207	    for (const auto &read : scalar_reads) {
208	      bool found = false;
209	      for (const auto &acc : current_accesses) {
210	        if (acc.buffer_name == read.buffer_name) {
211	          found = true;
212	          break;
213	        }
214	      }
215	      if (!found) {
216	        current_accesses.push_back(read);
217	      }
218	    }
219	
220	    if (current_accesses.empty()) {
221	      return GetRef<Stmt>(op);
222	    }
223	
224	    return ProcessStatement(GetRef<Stmt>(op), current_accesses);
225	  }
226	
227	  Stmt VisitStmt_(const LetStmtNode *op) override {
228	    auto scalar_reads = ScanBufferLoads(op->value);
229	
230	    if (scalar_reads.empty()) {
231	      Stmt new_body = VisitStmt(op->body);
232	      return LetStmt(op->var, op->value, new_body);
233	    }
234	
235	    return ProcessLetStatement(op, scalar_reads);
236	  }
237	
238	  Stmt VisitStmt_(const AttrStmtNode *op) override {
239	    if (op->attr_key == "resource_scope") {
240	      auto saved_access_history = current_access_history_;
241	      auto saved_write_history = current_write_history_;
242	      current_access_history_.clear();
243	      current_write_history_.clear();
244	      Stmt new_body = VisitStmt(op->body);
245	      current_access_history_ = saved_access_history;
246	      current_write_history_ = saved_write_history;
247	      return AttrStmt(op->node, op->attr_key, op->value, new_body);
248	    }
249	    Stmt new_body = VisitStmt(op->body);
250	    return AttrStmt(op->node, op->attr_key, op->value, new_body);
251	  }
252	
253	  Stmt VisitStmt_(const IfThenElseNode *op) override {
254	    auto saved_history = current_access_history_;
255	    auto saved_write_history = current_write_history_;
256	    Stmt then_case = VisitStmt(op->then_case);
257	
258	    auto then_history = current_access_history_;
259	    auto then_write_history = current_write_history_;
260	    current_access_history_ = saved_history;
261	    current_write_history_ = saved_write_history;
262	    Optional<Stmt> else_case;
263	    if (op->else_case.defined()) {
264	      else_case = VisitStmt(op->else_case.value());
265	    }
266	
267	    current_access_history_ = saved_history;
268	    current_write_history_ = saved_write_history;
269	    for (const auto &kv : then_history) {
270	      current_access_history_[kv.first] = kv.second;
271	    }
272	    for (const auto &kv : then_write_history) {
273	      current_write_history_[kv.first] = kv.second;
274	    }
275	    return IfThenElse(op->condition, then_case, else_case);
276	  }
277	
278	  Stmt VisitStmt_(const ForNode *op) override {
279	    if (is_revisit_pass_) {
280	      Stmt new_body = VisitStmt(op->body);
281	      return For(op->loop_var, op->min, op->extent, op->kind, new_body,
282	                 op->thread_binding, op->annotations);
283	    }
284	
285	    auto saved_history = current_access_history_;
286	    auto saved_write_history = current_write_history_;
287	    Stmt first_body = VisitStmt(op->body);
288	    auto end_history = current_access_history_;
289	    auto end_write_history = current_write_history_;
290	
291	    current_access_history_ = saved_history;
292	    current_write_history_ = saved_write_history;
293	    for (const auto &kv : end_history) {
294	      BufferAccess back_edge_access = kv.second;
295	      back_edge_access.is_back_edge = true;
296	      current_access_history_[kv.first] = back_edge_access;
297	    }
298	    for (const auto &kv : end_write_history) {
299	      BufferAccess back_edge_access = kv.second;
300	      back_edge_access.is_back_edge = true;
301	      current_write_history_[kv.first] = back_edge_access;
302	    }
303	
304	    is_revisit_pass_ = true;
305	    Stmt final_body = VisitStmt(first_body);
306	    is_revisit_pass_ = false;
307	
308	    current_access_history_ = end_history;
309	    current_write_history_ = end_write_history;
310	
311	    return For(op->loop_var, op->min, op->extent, op->kind, final_body,
312	               op->thread_binding, op->annotations);
313	  }
314	
315	  Stmt VisitStmt_(const AllocateNode *op) override {
316	    Stmt new_body = VisitStmt(op->body);
317	    return Allocate(op->buffer_var, op->dtype, op->extents, op->condition,
318	                    new_body);
319	  }
