321	  // ==================== Core processing ====================
322	
323	  void CheckBufferDependency(const BufferAccess &current_access,
324	                             const std::string &buffer_name,
325	                             std::vector<SyncRequirement> &sync_requirements) {
326	    // 1. Check last access (same-pipeline barrier, cross-pipeline WAR/WAW/RAW)
327	    auto access_it = current_access_history_.find(buffer_name);
328	    bool last_access_is_write = false;
329	    if (access_it != current_access_history_.end()) {
330	      const auto &latest = access_it->second;
331	      last_access_is_write = latest.is_write;
332	      if (HasDataDependency(latest, current_access)) {
333	        std::string sync_type = GetRequiredSyncType(latest, current_access);
334	        if (!sync_type.empty()) {
335	          sync_requirements.push_back({sync_type, current_access.buffer_name});
336	        }
337	      }
338	    }
339	
340	    // 2. Check last write (recovers RAW/WAW lost when a read overwrote the
341	    //    write in current_access_history_).  Skip when the last access IS a
342	    //    write — it was already checked above and is the same entry.
343	    if (!last_access_is_write) {
344	      auto write_it = current_write_history_.find(buffer_name);
345	      if (write_it != current_write_history_.end()) {
346	        const auto &last_write = write_it->second;
347	        if (HasDataDependency(last_write, current_access)) {
348	          std::string sync_type =
349	              GetRequiredSyncType(last_write, current_access);
350	          if (!sync_type.empty()) {
351	            sync_requirements.push_back(
352	                {sync_type, current_access.buffer_name});
353	          }
354	        }
355	      }
356	    }
357	  }
358	
359	  Stmt ProcessStatement(const Stmt &stmt,
360	                        const std::vector<BufferAccess> &current_accesses) {
361	    std::vector<BufferAccess> supported;
362	    for (const auto &access : current_accesses) {
363	      if (IsSupportedPipeline(access.pipeline)) {
364	        supported.push_back(access);
365	      }
366	    }
367	
368	    if (supported.empty()) {
369	      return stmt;
370	    }
371	
372	    std::vector<SyncRequirement> sync_requirements;
373	    for (const auto &current_access : supported) {
374	      std::vector<std::string> related =
375	          FindRelatedBuffers(current_access.buffer_name);
376	      for (const auto &buffer_name : related) {
377	        CheckBufferDependency(current_access, buffer_name, sync_requirements);
378	      }
379	    }
380	
381	    auto optimized_syncs = DedupSyncRequirements(sync_requirements);
382	
383	    std::vector<Stmt> stmts;
384	    for (const auto &sync_type : optimized_syncs) {
385	      InsertSynchronization(sync_type, stmts);
386	    }
387	
388	    UpdateSyncStatesAfterSync(optimized_syncs);
389	    stmts.push_back(stmt);
390	    UpdateLatestAccessHistory(supported);
391	
392	    if (stmts.size() == 1) {
393	      return stmts[0];
394	    }
395	    return SeqStmt(stmts);
396	  }
397	
398	  Stmt ProcessLetStatement(const LetStmtNode *op,
399	                           const std::vector<BufferAccess> &scalar_reads) {
400	    std::vector<SyncRequirement> sync_requirements;
401	    for (const auto &current_access : scalar_reads) {
402	      std::vector<std::string> related =
403	          FindRelatedBuffers(current_access.buffer_name);
404	      for (const auto &buffer_name : related) {
405	        CheckBufferDependency(current_access, buffer_name, sync_requirements);
406	      }
407	    }
408	
409	    auto optimized_syncs = DedupSyncRequirements(sync_requirements);
410	
411	    std::vector<Stmt> stmts;
412	    for (const auto &sync_type : optimized_syncs) {
413	      InsertSynchronization(sync_type, stmts);
414	    }
415	
416	    UpdateSyncStatesAfterSync(optimized_syncs);
417	    UpdateLatestAccessHistory(scalar_reads);
418	
419	    Stmt new_body = VisitStmt(op->body);
420	    stmts.push_back(LetStmt(op->var, op->value, new_body));
421	
422	    if (stmts.size() == 1) {
423	      return stmts[0];
424	    }
425	    return SeqStmt(stmts);
426	  }
427	
428	  // ==================== Analysis ====================
429	
430	  std::vector<BufferAccess> AnalyzeStmtAccesses(const Stmt &stmt) {
431	    std::vector<BufferAccess> accesses;
432	
433	    auto eval = stmt.as<EvaluateNode>();
434	    if (!eval) {
435	      return accesses;
436	    }
437	
438	    auto call = eval->value.as<CallNode>();
439	    if (!call) {
440	      return accesses;
441	    }
442	
443	    if (call->op.same_as(builtin::call_extern())) {
444	      std::string func_name = Downcast<StringImm>(call->args[0])->value;
445	      std::string normalized = NormalizeFunctionName(func_name);
446	      auto config_it = operation_config_.find(normalized);
447	      if (config_it != operation_config_.end()) {
448	        CollectBufferAccesses(config_it->second, normalized, call->args, 1,
449	                              accesses);
450	      }
451	    } else {
452	      auto *op_ptr = call->op.as<OpNode>();
453	      if (op_ptr) {
454	        std::string op_name = op_ptr->name;
455	        auto config_it = operation_config_.find(op_name);
456	        if (config_it != operation_config_.end()) {
457	          CollectBufferAccesses(config_it->second, op_name, call->args, 0,
458	                                accesses);
459	        }
460	      }
461	    }
462	
463	    return accesses;
464	  }
465	
466	  void CollectBufferAccesses(const OperationConfig &config,
467	                             const std::string &op_name,
468	                             const Array<PrimExpr> &call_args, size_t offset,
469	                             std::vector<BufferAccess> &accesses) {
470	    std::unordered_map<std::string, BufferAccess> buffer_access_map;
471	
472	    for (const auto &buffer_config : config.buffer_accesses) {
473	      size_t arg_index = buffer_config.first + offset;
474	      const std::string &access_type = buffer_config.second;
475	
476	      if (arg_index >= call_args.size()) {
477	        continue;
478	      }
479	
480	      auto buf_info = ExtractBufferInfoFromAccessPtr(call_args[arg_index]);
481	      if (buf_info.buffer_name.empty()) {
482	        continue;
483	      }
484	
485	      bool is_write = (access_type == "write");
486	      auto it = buffer_access_map.find(buf_info.buffer_name);
487	      if (it != buffer_access_map.end()) {
488	        if (is_write) {
489	          it->second.is_write = true;
490	        }
491	      } else {
492	        BufferAccess access;
493	        access.buffer_name = buf_info.buffer_name;
494	        access.is_write = is_write;
495	        access.pipeline = config.default_pipeline;
496	        access.operation = op_name;
497	        access.physical_address = GetPhysicalAddress(buf_info.buffer_name);
498	        buffer_access_map[buf_info.buffer_name] = access;
499	      }
500	    }
501	
502	    for (const auto &pair : buffer_access_map) {
503	      accesses.push_back(pair.second);
504	    }
505	  }
506	
507	  // ExprVisitor-based collector that finds all BufferLoad nodes anywhere in
508	  // an expression tree (including inside Add/Mul/Cast/Select/Call, etc.).
509	  // The previous hand-rolled recursion only visited BufferLoadNode and
510	  // CallNode, silently missing loads nested in arithmetic or logical ops.
511	  class BufferLoadCollector : public ExprVisitor {
512	  public:
513	    BufferLoadCollector(std::vector<BufferAccess> *accesses,
514	                        AscendSyncInsertVS *pass)
515	        : accesses_(accesses), pass_(pass) {}
516	
517	    void VisitExpr_(const BufferLoadNode *op) override {
518	      std::string scope = GetPtrStorageScope(op->buffer->data);
519	      if (scope != "local.var" && scope != "n") {
520	        BufferAccess access;
521	        access.buffer_name = op->buffer->data->name_hint;
522	        access.is_write = false;
523	        access.pipeline = "PIPE_S";
524	        access.operation = "BufferLoad";
525	        access.physical_address = pass_->GetPhysicalAddress(access.buffer_name);
526	        accesses_->push_back(access);
527	      }
528	      ExprVisitor::VisitExpr_(op);
529	    }
530	
531	  private:
532	    std::vector<BufferAccess> *accesses_;
533	    AscendSyncInsertVS *pass_;
534	  };
535	
536	  std::vector<BufferAccess> ScanBufferLoads(const PrimExpr &expr) {
537	    std::vector<BufferAccess> accesses;
538	    BufferLoadCollector collector(&accesses, this);
539	    collector(expr);
540	    return accesses;
541	  }
542	
543	  bool HasDataDependency(const BufferAccess &prev, const BufferAccess &curr) {
544	    bool shares_memory = false;
545	
546	    if (prev.buffer_name == curr.buffer_name) {
547	      shares_memory = true;
548	    } else if (prev.physical_address != -1 && curr.physical_address != -1) {
549	      int64_t prev_size = GetBufferSize(prev.buffer_name);
550	      int64_t curr_size = GetBufferSize(curr.buffer_name);
551	      if (prev_size > 0 && curr_size > 0) {
552	        int64_t prev_end = prev.physical_address + prev_size;
553	        int64_t curr_end = curr.physical_address + curr_size;
554	        shares_memory = (prev.physical_address < curr_end &&
555	                         curr.physical_address < prev_end);
556	      } else {
557	        shares_memory = (prev.physical_address == curr.physical_address);
558	      }
559	    }
560	
561	    if (shares_memory) {
562	      // Only WAW, RAW, WAR are real hazards. RAR (both reads) has no hazard.
563	      // Cross-pipeline RAW/WAR dependencies that were lost when a read
564	      // overwrote a write in current_access_history_ are recovered via
565	      // current_write_history_ in ProcessStatement/ProcessLetStatement.
566	      if (prev.is_write || curr.is_write) {
567	        return true;
568	      }
569	    }
570	    return false;
571	  }
572	
573	  std::string GetRequiredSyncType(const BufferAccess &prev_access,
574	                                  const BufferAccess &curr_access) {
575	    if (!ShouldSync(prev_access.pipeline, curr_access.pipeline)) {
576	      return "";
577	    }
578	
579	    if (is_revisit_pass_ && !prev_access.is_back_edge) {
580	      return "";
581	    }
582	
583	    if (prev_access.pipeline == curr_access.pipeline) {
584	      std::string barrier = "PipeBarrier_" + prev_access.pipeline;
585	      if (prev_access.pipe_barriers.find(barrier) !=
586	          prev_access.pipe_barriers.end()) {
587	        return "";
588	      }
589	      return barrier;
590	    }
591	
592	    std::string event_type =
593	        GetEventType(prev_access.pipeline, curr_access.pipeline);
594	    if (!event_type.empty()) {
595	      std::string event_sync = "EventPair_" + event_type;
596	      if (prev_access.event_pairs.find(event_sync) !=
597	          prev_access.event_pairs.end()) {
598	        return "";
599	      }
600	      return event_sync;
601	    }
602	    return "";
603	  }
604	
605	  std::string GetEventType(const std::string &src_pipeline,
606	                           const std::string &dst_pipeline) {
607	    std::string key = src_pipeline + "_" + dst_pipeline;
608	    auto it = event_mapping_.find(key);
609	    return it != event_mapping_.end() ? it->second : "";
610	  }
611	
612	  // ==================== Address / size / scope ====================
613	
614	  int64_t GetPhysicalAddress(const std::string &buffer_name) {
615	    for (const auto &pair : address_map_) {
616	      if (pair.first->name_hint == buffer_name) {
617	        if (auto int_imm = pair.second.as<IntImmNode>()) {
618	          return int_imm->value;
619	        }
620	      }
621	    }
622	    return -1;
623	  }
624	
625	  int64_t GetBufferSize(const std::string &buffer_name) {
626	    for (const auto &pair : size_map_) {
627	      if (pair.first->name_hint == buffer_name) {
628	        if (auto int_imm = pair.second.as<IntImmNode>()) {
629	          return int_imm->value;
630	        }
631	      }
632	    }
633	    return -1;
634	  }
635	
636	  std::string GetBufferScope(const std::string &buffer_name) {
637	    for (const auto &pair : address_map_) {
638	      if (pair.first->name_hint == buffer_name) {
639	        return GetPtrStorageScope(pair.first);
640	      }
641	    }
642	    return "";
643	  }
644	
645	  std::vector<std::string> FindRelatedBuffers(const std::string &buffer_name) {
646	    std::vector<std::string> related;
647	    int64_t target_addr = GetPhysicalAddress(buffer_name);
648	
649	    if (target_addr == -1) {
650	      related.push_back(buffer_name);
651	      return related;
652	    }
653	
654	    std::string target_scope = GetBufferScope(buffer_name);
655	    int64_t target_size = GetBufferSize(buffer_name);
656	
657	    if (target_size <= 0) {
658	      for (const auto &pair : address_map_) {
659	        if (auto int_imm = pair.second.as<IntImmNode>()) {
660	          if (GetPtrStorageScope(pair.first) != target_scope) {
661	            continue;
662	          }
663	          int64_t other_addr = int_imm->value;
664	          int64_t other_size = GetBufferSize(pair.first->name_hint);
665	          if (other_size > 0) {
666	            if (other_addr <= target_addr &&
667	                target_addr < other_addr + other_size) {
668	              related.push_back(pair.first->name_hint);
669	            }
670	          } else if (other_addr == target_addr) {
671	            related.push_back(pair.first->name_hint);
672	          }
673	        }
674	      }
675	      return related;
676	    }
677	
678	    int64_t target_end = target_addr + target_size;
679	
680	    for (const auto &pair : address_map_) {
681	      if (auto int_imm = pair.second.as<IntImmNode>()) {
682	        if (GetPtrStorageScope(pair.first) != target_scope) {
683	          continue;
684	        }
685	        int64_t other_addr = int_imm->value;
686	        int64_t other_size = GetBufferSize(pair.first->name_hint);
687	        if (other_size <= 0) {
688	          if (other_addr == target_addr) {
689	            related.push_back(pair.first->name_hint);
690	          }
691	          continue;
692	        }
693	        int64_t other_end = other_addr + other_size;
694	        if (target_addr < other_end && other_addr < target_end) {
695	          related.push_back(pair.first->name_hint);
696	        }
697	      }
698	    }
699	    return related;
700	  }
701	
702	  // ==================== Name extraction ====================
703	
704	  std::string NormalizeFunctionName(const std::string &func_name) {
705	    std::string result = func_name;
706	    size_t template_pos = result.find('<');
707	    if (template_pos != std::string::npos) {
708	      result = result.substr(0, template_pos);
709	    }
710	    size_t ns_pos = result.find("tl::ascend::");
711	    if (ns_pos != std::string::npos) {
712	      result = result.substr(ns_pos + 12);
713	    }
714	    return result;
715	  }
716	
717	  BufferInfo ExtractBufferInfoFromAccessPtr(const PrimExpr &expr) {
718	    BufferInfo info = {"", false, false};
719	
720	    if (auto var = expr.as<VarNode>()) {
721	      info.buffer_name = var->name_hint;
722	      return info;
723	    }
724	
725	    auto call = expr.as<CallNode>();
726	    if (!call) {
727	      return info;
728	    }
729	
730	    if (call->op.same_as(builtin::tvm_access_ptr())) {
731	      if (call->args.size() >= 5) {
732	        if (auto var = call->args[1].as<VarNode>()) {
733	          info.buffer_name = var->name_hint;
734	        }
735	        if (auto access_mask = call->args[4].as<IntImmNode>()) {
736	          int mask = access_mask->value;
737	          info.is_read = (mask & 1) != 0;
738	          info.is_write = (mask & 2) != 0;
739	        }
740	      }
741	    } else {
742	      if (call->args.size() >= 2) {
743	        if (auto var = call->args[1].as<VarNode>()) {
744	          info.buffer_name = var->name_hint;
745	          info.is_read = true;
746	          info.is_write = true;
747	        }
748	      }
749	    }
750	
751	    return info;
752	  }
753	
754	  // ==================== Sync generation ====================
755	
756	  void InsertSynchronization(const std::string &sync_type,
757	                             std::vector<Stmt> &stmts) {
758	    if (sync_type == "PipeBarrier_ALL") {
759	      stmts.push_back(CreatePipeBarrier("PIPE_ALL"));
760	    } else if (sync_type.find("PipeBarrier_") == 0) {
761	      std::string pipeline = sync_type.substr(12);
762	      if (pipeline == "PIPE_V" && platform_ == "A5") {
763	        // A5 does not support pipe_barrier(PIPE_V);
764	        // raise error: the range of 1st parameter must be [4, 6]
765	        // use V_V event pair
766	        int event_id = AllocateEventId();
767	        stmts.push_back(CreateSetFlag("V_V", event_id));
768	        stmts.push_back(CreateWaitFlag("V_V", event_id));
769	      } else {
770	        stmts.push_back(CreatePipeBarrier(pipeline));
771	      }
772	    } else if (sync_type.find("EventPair_") == 0) {
773	      std::string event_type = sync_type.substr(10);
774	      int event_id = AllocateEventId();
775	      stmts.push_back(CreateSetFlag(event_type, event_id));
776	      stmts.push_back(CreateWaitFlag(event_type, event_id));
777	    }
778	  }
779	
780	  int AllocateEventId() {
781	    event_id_counter_ = (event_id_counter_ + 1) % 8;
782	    return event_id_counter_;
783	  }
784	
785	  Stmt CreatePipeBarrier(const std::string &pipeline) {
786	    Array<PrimExpr> args = {StringImm(pipeline)};
787	    return Evaluate(
788	        Call(DataType::Handle(), Op::Get("tl.ascend_auto_barrier"), args));
789	  }
790	
791	  Stmt CreateSetFlag(const std::string &event_type, int event_id) {
792	    Array<PrimExpr> args = {StringImm(event_type),
793	                            IntImm(DataType::Int(32), event_id)};
794	    return Evaluate(
795	        Call(DataType::Handle(), Op::Get("tl.ascend_auto_set_flag"), args));
796	  }
797	
798	  Stmt CreateWaitFlag(const std::string &event_type, int event_id) {
799	    Array<PrimExpr> args = {StringImm(event_type),
800	                            IntImm(DataType::Int(32), event_id)};
801	    return Evaluate(
802	        Call(DataType::Handle(), Op::Get("tl.ascend_auto_wait_flag"), args));
803	  }
804	
805	  // ==================== State management ====================
806	
807	  std::vector<std::string>
808	  DedupSyncRequirements(std::vector<SyncRequirement> &requirements) {
809	    if (requirements.empty()) {
810	      return {};
811	    }
812	
813	    std::sort(requirements.begin(), requirements.end(),
814	              [](const SyncRequirement &a, const SyncRequirement &b) {
815	                return a.sync_type < b.sync_type;
816	              });
817	
818	    std::vector<std::string> unique_syncs;
819	    for (const auto &req : requirements) {
820	      if (unique_syncs.empty() || unique_syncs.back() != req.sync_type) {
821	        unique_syncs.push_back(req.sync_type);
822	      }
823	    }
824	    return unique_syncs;
825	  }
826	
827	  void
828	  UpdateSyncStatesAfterSync(const std::vector<std::string> &inserted_syncs) {
829	    auto update_hist =
830	        [&](std::unordered_map<std::string, BufferAccess> &hist) {
831	          for (auto &pair : hist) {
832	            BufferAccess &access = pair.second;
833	            for (const auto &sync_type : inserted_syncs) {
834	              if (sync_type.find("PipeBarrier_") == 0) {
835	                std::string pipeline = sync_type.substr(12);
836	                if (access.pipeline == pipeline) {
837	                  access.pipe_barriers.insert(sync_type);
838	                }
839	              } else if (sync_type.find("EventPair_") == 0) {
840	                std::string event_type = sync_type.substr(10);
841	                size_t pos = event_type.find('_');
842	                if (pos != std::string::npos) {
843	                  std::string src_pipeline =
844	                      "PIPE_" + event_type.substr(0, pos);
845	                  if (access.pipeline == src_pipeline) {
846	                    access.event_pairs.insert(sync_type);
847	                  }
848	                }
849	              }
850	            }
851	          }
852	        };
853	    update_hist(current_access_history_);
854	    update_hist(current_write_history_);
855	  }
856	
857	  void
858	  UpdateLatestAccessHistory(const std::vector<BufferAccess> &current_accesses) {
859	    for (const auto &access : current_accesses) {
860	      if (is_revisit_pass_) {
861	        auto it = current_access_history_.find(access.buffer_name);
862	        if (it != current_access_history_.end() && it->second.is_back_edge &&
863	            !ShouldSync(it->second.pipeline, access.pipeline)) {
864	          continue;
865	        }
866	      }
867	      current_access_history_[access.buffer_name] = access;
868	      if (access.is_write) {
869	        current_write_history_[access.buffer_name] = access;
870	      }
871	    }
872	  }
873	
874	  // ==================== Pipeline filtering ====================
875	
876	  bool IsSupportedPipeline(const std::string &p) {
877	    return p == "PIPE_V" || p == "PIPE_S" || p == "PIPE_MTE2" ||
878	           p == "PIPE_MTE3";
879	  }
880	
881	  bool ShouldSync(const std::string &a, const std::string &b) {
882	    if (!IsSupportedPipeline(a) || !IsSupportedPipeline(b)) {
883	      return false;
884	    }
885	    // V->V (same pipeline)
886	    if (a == "PIPE_V" && b == "PIPE_V") {
887	      return true;
888	    }
889	    // S <-> other (but not S->S, scalar pipeline is in-order)
890	    if ((a == "PIPE_S" || b == "PIPE_S") && a != b) {
891	      return true;
892	    }
893	    return false;
894	  }
895	
896	  // ==================== Members ====================
897	
898	  int event_id_counter_ = 0;
899	  bool is_revisit_pass_ = false;
900	  std::unordered_map<std::string, std::string> event_mapping_;
901	  std::unordered_map<std::string, OperationConfig> operation_config_;
902	  std::unordered_map<std::string, BufferAccess> current_access_history_;
903	  std::unordered_map<std::string, BufferAccess> current_write_history_;
904	  Map<Var, PrimExpr> address_map_;
905	  Map<Var, PrimExpr> size_map_;
906	  std::string platform_;
907	  Target target_;
908	};
909	
910	tvm::transform::Pass AscendSyncInsertVS(Target target, std::string platform) {
911	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
912	    return AscendSyncInsertVS::Substitute(std::move(f), ctx, target, platform);
913	  };
914	  return CreatePrimFuncPass(pass_func, 0, "tl.AscendSyncInsertVS", {});
915	}
916	
917	TVM_REGISTER_GLOBAL("tl.transform.AscendSyncInsertVS")
918	    .set_body_typed(AscendSyncInsertVS);
919	
920	} // namespace tl
921	} // namespace tvm
